import test from'node:test';import assert from'node:assert/strict';import{create,reduce,validate,model}from'./state.js';
test('moving and redefining mechanism keeps causal notes but requests a review',()=>{let w=create();const o=w.options[0],why=o.why;w=reduce(w,{type:'move-option',id:o.id,value:'goal',anchor:o.anchor});assert.equal(w.options[0].level,'goal');assert.equal(w.options[0].why,why);assert.equal(w.options[0].review,true);w=reduce(w,{type:'reviewed',id:o.id});w=reduce(w,{type:'step',id:o.anchor,field:'mechanism',value:'Changed cause'});assert.equal(w.options[0].review,true);});
test('removing a referenced mechanism is rejected and portable exports preserve choices',()=>{let w=create();assert.throws(()=>reduce(w,{type:'remove-step',id:w.steps[0].id}));w=reduce(w,{type:'choose',id:w.options[0].id});assert.deepEqual(model.parse(model.serialize(w)),validate(w));});
